    public CampaignService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new CampaignEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(CampaignRepository.class) );
		this.validator		= applicationContext.getBean(CampaignValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Campaign
	 */
		public Campaign createCampaign( CreateCampaignCommand command ) {

		Campaign entity = new Campaign();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setCampaignId( command.getCampaignId() );
            entity.setName( command.getName() );
            entity.setTotalBudget( command.getTotalBudget() );
            entity.setFlight( command.getFlight() );
            entity.setObjective( command.getObjective() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Campaign {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateCampaignCommand
	 * @return		Campaign
	 */
	public Campaign updateCampaign( UpdateCampaignCommand command ) {

		Campaign entity = new Campaign();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setCampaignId( command.getCampaignId() );
            entity.setName( command.getName() );
            entity.setTotalBudget( command.getTotalBudget() );
            entity.setFlight( command.getFlight() );
            entity.setAdAccount( command.getAdAccount() );
            entity.setLineItems( command.getLineItems() );
            entity.setKpis( command.getKpis() );
            entity.setTrackingPixels( command.getTrackingPixels() );
            entity.setAudiences( command.getAudiences() );
            entity.setReports( command.getReports() );
            entity.setInsertionOrder( command.getInsertionOrder() );
            entity.setObjective( command.getObjective() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Campaign {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteCampaignCommand
	 */
	public void delete( DeleteCampaignCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getCampaignId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Campaign {0} ", id );

	}

	/**
	 * Method to retrieve the Campaign via CampaignFetchOneSummary
	 * @param 	summary CampaignFetchOneSummary
	 * @return 	CampaignFetchOneResponse
	 */
	public Campaign getCampaign( CampaignFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "CampaignFetchOneSummary arg cannot be null" );

		Campaign entity = null;
		UUID id = summary.getCampaignId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Campaign using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Campaigns
	 *
	 * @return 	List<Campaign>
	 */
    public List<Campaign> getAllCampaign() {
		List<Campaign> list = projector.findAll( new FindAllCampaignQuery() );
		return list;
	}

